CREATE TABLE "SavedSecretResource" ("id" TEXT NOT NULL PRIMARY KEY, "ownerAccountId" TEXT NOT NULL, "displayName" TEXT NOT NULL, "kind" TEXT NOT NULL, "encryptionMode" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 1, "storedContent" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "SavedSecretResource_ownerAccountId_fkey" FOREIGN KEY ("ownerAccountId") REFERENCES "Account" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "SavedSecretAccountGrant" ("resourceId" TEXT NOT NULL, "accountId" TEXT NOT NULL, "createdByAccountId" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("resourceId","accountId"), CONSTRAINT "SavedSecretAccountGrant_resourceId_fkey" FOREIGN KEY ("resourceId") REFERENCES "SavedSecretResource" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SavedSecretAccountGrant_accountId_fkey" FOREIGN KEY ("accountId") REFERENCES "Account" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SavedSecretAccountGrant_createdByAccountId_fkey" FOREIGN KEY ("createdByAccountId") REFERENCES "Account" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "SavedSecretTeamGrant" ("resourceId" TEXT NOT NULL, "teamId" TEXT NOT NULL, "createdByAccountId" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("resourceId","teamId"), CONSTRAINT "SavedSecretTeamGrant_resourceId_fkey" FOREIGN KEY ("resourceId") REFERENCES "SavedSecretResource" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SavedSecretTeamGrant_teamId_fkey" FOREIGN KEY ("teamId") REFERENCES "Team" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SavedSecretTeamGrant_createdByAccountId_fkey" FOREIGN KEY ("createdByAccountId") REFERENCES "Account" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "SavedSecretGroupGrant" ("resourceId" TEXT NOT NULL, "teamGroupId" TEXT NOT NULL, "createdByAccountId" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("resourceId","teamGroupId"), CONSTRAINT "SavedSecretGroupGrant_resourceId_fkey" FOREIGN KEY ("resourceId") REFERENCES "SavedSecretResource" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SavedSecretGroupGrant_teamGroupId_fkey" FOREIGN KEY ("teamGroupId") REFERENCES "TeamGroup" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SavedSecretGroupGrant_createdByAccountId_fkey" FOREIGN KEY ("createdByAccountId") REFERENCES "Account" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "SavedSecretResourceKeyEnvelope" ("resourceId" TEXT NOT NULL, "recipientAccountId" TEXT NOT NULL, "encryptedDataKey" BLOB NOT NULL, "recipientContentPublicKeyFingerprint" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, PRIMARY KEY ("resourceId","recipientAccountId"), CONSTRAINT "SavedSecretResourceKeyEnvelope_resourceId_fkey" FOREIGN KEY ("resourceId") REFERENCES "SavedSecretResource" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SavedSecretResourceKeyEnvelope_recipientAccountId_fkey" FOREIGN KEY ("recipientAccountId") REFERENCES "Account" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "SavedSecretResource_owner_updated_idx" ON "SavedSecretResource" ("ownerAccountId","updatedAt");
CREATE INDEX "SavedSecretAccountGrant_accountId_resourceId_idx" ON "SavedSecretAccountGrant" ("accountId","resourceId");
CREATE INDEX "SavedSecretTeamGrant_teamId_resourceId_idx" ON "SavedSecretTeamGrant" ("teamId","resourceId");
CREATE INDEX "SavedSecretGroupGrant_teamGroupId_resourceId_idx" ON "SavedSecretGroupGrant" ("teamGroupId","resourceId");
CREATE INDEX "SavedSecretResourceKeyEnvelope_recipientAccountId_resourceId_idx" ON "SavedSecretResourceKeyEnvelope" ("recipientAccountId","resourceId");
